package in.anumati.platform.grievance; import in.anumati.platform.application.ApplicationRecord; import in.anumati.platform.business.BusinessProfile; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="grievances") public class Grievance { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="business_profile_id",nullable=false) private BusinessProfile businessProfile; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="application_id") private ApplicationRecord application; @Column(nullable=false,length=200) private String subject; @Column(nullable=false,length=5000) private String description; @Column(length=200) private String department; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private GrievancePriority priority; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private GrievanceStatus status; @Column(length=100) private String assignedTo; @Column(length=5000) private String resolution; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; private Instant closedAt; protected Grievance(){} public Grievance(BusinessProfile p,ApplicationRecord a,String subject,String desc,String dept,GrievancePriority pr){id=UUID.randomUUID();businessProfile=p;application=a;this.subject=subject;description=desc;department=dept;priority=pr;status=GrievanceStatus.OPEN;createdAt=Instant.now();updatedAt=createdAt;} public void assign(String actor){assignedTo=actor;status=GrievanceStatus.ASSIGNED;updatedAt=Instant.now();} public void progress(){status=GrievanceStatus.IN_PROGRESS;updatedAt=Instant.now();} public void resolve(String r){resolution=r;status=GrievanceStatus.RESOLVED;updatedAt=Instant.now();closedAt=Instant.now();} public void close(){status=GrievanceStatus.CLOSED;updatedAt=Instant.now();closedAt=Instant.now();} public UUID getId(){return id;}public BusinessProfile getBusinessProfile(){return businessProfile;}public ApplicationRecord getApplication(){return application;}public String getSubject(){return subject;}public String getDescription(){return description;}public String getDepartment(){return department;}public GrievancePriority getPriority(){return priority;}public GrievanceStatus getStatus(){return status;}public String getAssignedTo(){return assignedTo;}public String getResolution(){return resolution;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public Instant getClosedAt(){return closedAt;}}
